 schemas=[T.article_schema(title=title,description=desc,url=T.SITE+path,published=DATE,modified=DATE,section=x['cluster'],keywords=[title,x['cluster']],citations=[S[k] for k in x['source']]),T.faq_schema(faqs),T.breadcrumb_schema([('Home','/'),('FAQ','/faq/'),(title,path)])]
 T.write_page(path,T.build_page(title=('S Corp Health Insurance: Spouse Employer Coverage' if x['slug']=='s-corp-health-insurance-spouse-employer-plan' else (title+' | AE Tax' if len(title)<=60 else title)),description=desc,path=path,body=body,schemas=schemas,published=DATE,modified=DATE))
